-- ==============================================================
-- Customer Profiles : INBOUND IMPORT from the Excel template
-- (CustomerProfiles_Inbound_Import.xlsx)
-- --------------------------------------------------------------
-- Source : MotozonebikeCustomer_01_Dec_2025_to_10_Nov_2026.xlsx
--   314 rows in the file; 313 are below (cleaned). Left out :
--   ORGANIK CHICKEN PLC (same phone as ORGANIK CHICKEN LIMITED).
--   Added "as is", to be completed on the form later (Remarks say
--   what is missing; list in MotozoneCustomers_NotImported.xlsx,
--   sheet "To Complete Later") :
--   - 26 people without a valid NID : NID left empty
--   - AKHI AKTER : phone 0194744493 (10 digits) kept as it is
--   - GRAMEEN DISTRIBUTION LTD, S. ALAM ENGINERING (Corporate) :
--     no usable phone, a placeholder 00000000001 / 00000000002 is
--     used until the real phone is entered
-- Cleaned before writing this script :
--   - the " - <phone>" after the name removed
--   - "Please insert ...", "NULL", "DOB", "0000" left empty
--   - Date of Birth read from dd/mm/yyyy or dd-mm-yyyy
--   - Registration Address = Present Address
--   - companies (LTD / LIMITED / PLC / HOTEL ..., SPEED NET,
--     MOBILE CANVAS) marked Corporate : as on the form they keep
--     no NID, Date of Birth or parents' names (TIN / BIN empty,
--     to be filled on the form)
--
-- Run the whole script once in pgAdmin (Query Tool) on the App
-- database, then read the result table at the bottom : every row
-- shows ADDED (with its new code) or SKIPPED (with the reason).
--
-- Built the same way as the Customer Profiles form :
--   - Customer Type = Inbound; code CIB-000001 ... continuing
--     after the highest code ever used (previous codes included)
--   - names / addresses in CAPITALS; Display Name =
--     "<NAME> - <PHONE 1>"
--   - every customer gets its receivable ledger
--     GLR-ccc-ggg-sss-nnnnn under SUB-002-002-006 (Trade
--     Receivables), named like the customer
--
-- Safe to run again : a phone already on a customer, or an NID
-- already on an Inbound customer, is skipped (never doubled).
-- All rows are added in one transaction : any error adds none.
-- ==============================================================

DROP TABLE IF EXISTS tmp_customer_import;

CREATE TEMP TABLE tmp_customer_import
(
    row_no          serial,
    sl              text,
    customer_name   text,
    father_name     text,
    mother_name     text,
    date_of_birth   text,
    phone1          text,
    phone2          text,
    email           text,
    nid_no          text,
    driving_license text,
    present_address text,
    permanent_addr  text,
    registration_addr text,
    location_text   text,
    credit_limit    text,
    remarks         text,
    status_text     text,
    is_corporate    boolean DEFAULT false,
    -- true : added as it is (NID / phone / address may be missing)
    keep_as_is      boolean DEFAULT false,
    -- filled by the script
    result          text DEFAULT '',
    customer_code   text DEFAULT '',
    ledger_code     text DEFAULT '',
    location_name   text DEFAULT ''
);

