INSERT INTO tmp_customer_import (sl, customer_name, father_name, mother_name, date_of_birth, phone1, nid_no, present_address, permanent_addr, registration_addr, remarks, is_corporate, keep_as_is) VALUES ('314', 'ZAWAD UL HASAN', 'ZAMIUL HASAN', 'UMME KULSUM', '28-11-2007', '01570277436', '1532374798', 'H-57,R-06,S-04,UTTARA,DHAKA', 'H-57,R-06,S-04,UTTARA,DHAKA', 'H-57,R-06,S-04,UTTARA,DHAKA', '', false, false);
INSERT INTO tmp_customer_import (sl, customer_name, father_name, mother_name, date_of_birth, phone1, nid_no, present_address, permanent_addr, registration_addr, remarks, is_corporate, keep_as_is) VALUES ('315', 'ZUBAIDA JESMIN SUNAINA', 'MARUF HOSSAIN', 'SAMSIA JESMIN', '02-09-2005', '01632106847', '8731137538', 'H-50,R-13,S-12,UTTARA,DHAKA', 'H-50,R-13,S-12,UTTARA,DHAKA', 'H-50,R-13,S-12,UTTARA,DHAKA', '', false, false);
-- ================= DATA END ===================================

DO $$
DECLARE
    -- CreatedBy (1 = System)
    v_user_id    bigint := 1;

    sg           record;
    r            record;
    v_parent     text;
    v_ledger_no  int;
    v_cib_no     int;
    v_code       text;
    v_ledger     text;
    v_display    text;
    v_name       text;
    v_dob        date;
    v_credit     numeric(18, 2);
    v_location   bigint;
    v_loc_count  int;
    v_reason     text;
    v_added      int := 0;
    v_skipped    int := 0;
BEGIN
    ------------------------------------------------------------
    -- Clean the pasted text : trim, CAPITALS, digits only
    ------------------------------------------------------------
    UPDATE tmp_customer_import
       SET sl                = btrim(COALESCE(sl, '')),
           customer_name     = upper(regexp_replace(btrim(COALESCE(customer_name, '')), '\s+', ' ', 'g')),
           father_name       = upper(regexp_replace(btrim(COALESCE(father_name, '')), '\s+', ' ', 'g')),
           mother_name       = upper(regexp_replace(btrim(COALESCE(mother_name, '')), '\s+', ' ', 'g')),
           date_of_birth     = btrim(COALESCE(date_of_birth, '')),
           phone1            = regexp_replace(COALESCE(phone1, ''), '[^0-9]', '', 'g'),
           phone2            = regexp_replace(COALESCE(phone2, ''), '[^0-9]', '', 'g'),
           email             = lower(btrim(COALESCE(email, ''))),
           nid_no            = regexp_replace(COALESCE(nid_no, ''), '[^0-9]', '', 'g'),
           driving_license   = upper(btrim(COALESCE(driving_license, ''))),
           present_address   = upper(regexp_replace(btrim(COALESCE(present_address, '')), '\s+', ' ', 'g')),
           permanent_addr    = upper(regexp_replace(btrim(COALESCE(permanent_addr, '')), '\s+', ' ', 'g')),
           registration_addr = upper(regexp_replace(btrim(COALESCE(registration_addr, '')), '\s+', ' ', 'g')),
           location_text     = btrim(COALESCE(location_text, '')),
           credit_limit      = btrim(COALESCE(credit_limit, '')),
           remarks           = btrim(COALESCE(remarks, '')),
           status_text       = lower(btrim(COALESCE(status_text, '')));

    -- Phone written with a missing leading 0 (Excel number)
    UPDATE tmp_customer_import
       SET phone1 = '0' || phone1
     WHERE phone1 ~ '^1[0-9]{9}$';

    UPDATE tmp_customer_import
       SET phone2 = '0' || phone2
     WHERE phone2 ~ '^1[0-9]{9}$';

    -- Empty rows (nothing typed) are ignored
    DELETE FROM tmp_customer_import
     WHERE customer_name = '' AND phone1 = '' AND nid_no = ''
       AND present_address = '';

    ------------------------------------------------------------
    -- Receivable sub group (by CODE)
    ------------------------------------------------------------
    SELECT "AccountClassId", "AccountGroupId", "AccountSubGroupId",
           "ClassCode", "Mode", "GroupCode", "SubGroupCode"
      INTO sg
      FROM "AccountSubGroups"
     WHERE "SubGroupCode" = 'SUB-002-002-006'
       AND NOT "IsDeleted"
     LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Sub group SUB-002-002-006 (Trade Receivables) not found or deleted.';
    END IF;

    v_parent :=
        'GLR-'
        || lpad(substring(sg."ClassCode"    FROM '([0-9]+)$'), 3, '0') || '-'
        || lpad(substring(sg."GroupCode"    FROM '([0-9]+)$'), 3, '0') || '-'
        || lpad(substring(sg."SubGroupCode" FROM '([0-9]+)$'), 3, '0') || '-';

    ------------------------------------------------------------
    -- Highest numbers used so far
    ------------------------------------------------------------
    SELECT COALESCE(MAX(substring(c FROM '([0-9]+)$')::int), 0)
      INTO v_ledger_no
      FROM (
            SELECT "LedgerCode" AS c
              FROM "GeneralLedgers"
             WHERE "LedgerCode" LIKE v_parent || '%'
            UNION ALL
            SELECT "ReceivableLedgerCode"
              FROM "CustomerProfiles"
             WHERE "ReceivableLedgerCode" LIKE v_parent || '%'
           ) t
     WHERE c ~ '^GLR-[0-9]{3}-[0-9]{3}-[0-9]{3}-[0-9]+$';

    SELECT COALESCE(MAX(substring(c FROM 5)::int), 0)
      INTO v_cib_no
      FROM (
            SELECT "CustomerCode" AS c FROM "CustomerProfiles"
            UNION ALL
            SELECT "PreviousCode" FROM "CustomerProfiles"
           ) t
     WHERE c ~ '^CIB-[0-9]+$';

    ------------------------------------------------------------
    -- One row at a time, in sheet order
    ------------------------------------------------------------
    FOR r IN
        SELECT * FROM tmp_customer_import ORDER BY row_no
    LOOP
        v_reason := '';
        v_dob    := NULL;
        v_credit := 0;
        v_location := NULL;

        -- Required fields and formats
        IF r.customer_name = '' THEN
            v_reason := 'Customer Name is empty';
        ELSIF length(r.customer_name) > 150 THEN
            v_reason := 'Customer Name is longer than 150';
        ELSIF r.phone1 = '' OR length(r.phone1) > 11 THEN
            v_reason := 'Phone 1 is empty or longer than 11 digits';
        ELSIF NOT r.keep_as_is AND r.phone1 !~ '^01[0-9]{9}$' THEN
            v_reason := 'Phone 1 must be 11 digits starting 01 (' || r.phone1 || ')';
        ELSIF r.phone2 <> '' AND r.phone2 !~ '^01[0-9]{9}$' THEN
            v_reason := 'Phone 2 must be 11 digits starting 01 (' || r.phone2 || ')';
        ELSIF NOT r.is_corporate AND NOT (r.keep_as_is AND r.nid_no = '')
          AND r.nid_no !~ '^([0-9]{10}|[0-9]{13}|[0-9]{17})$' THEN
            v_reason := 'NID must be 10, 13 or 17 digits (' || r.nid_no || ')';
        ELSIF r.present_address = '' AND NOT r.keep_as_is THEN
            v_reason := 'Present Address is empty';
        ELSIF length(r.father_name) > 150 OR length(r.mother_name) > 150
           OR length(r.email) > 150 OR length(r.driving_license) > 30
           OR length(r.present_address) > 500 OR length(r.permanent_addr) > 500
           OR length(r.registration_addr) > 500 OR length(r.remarks) > 1000 THEN
            v_reason := 'A field is too long (Father / Mother / Email 150, License 30, Address 500, Remarks 1000)';
        ELSIF r.status_text NOT IN ('', 'active', 'inactive') THEN
            v_reason := 'Status must be Active or Inactive';
        END IF;

        -- Date of birth : dd-mm-yyyy (also dd/mm/yyyy, yyyy-mm-dd)
        IF v_reason = '' AND r.date_of_birth <> '' THEN
            BEGIN
                IF r.date_of_birth ~ '^[0-9]{1,2}[-/.][0-9]{1,2}[-/.][0-9]{4}$' THEN
                    v_dob := to_date(regexp_replace(r.date_of_birth, '[/.]', '-', 'g'), 'DD-MM-YYYY');
                ELSIF r.date_of_birth ~ '^[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}$' THEN
                    v_dob := to_date(r.date_of_birth, 'YYYY-MM-DD');
                ELSE
                    v_reason := 'Date of Birth must be dd-mm-yyyy (' || r.date_of_birth || ')';
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_reason := 'Date of Birth is not a real date (' || r.date_of_birth || ')';
            END;

            IF v_reason = '' AND v_dob > CURRENT_DATE THEN
                v_reason := 'Date of Birth is in the future';
            END IF;
        END IF;

        -- Credit limit
        IF v_reason = '' AND r.credit_limit <> '' THEN
            IF replace(r.credit_limit, ',', '') ~ '^[0-9]+(\.[0-9]{1,2})?$' THEN
                v_credit := replace(r.credit_limit, ',', '')::numeric(18, 2);
            ELSE
                v_reason := 'Credit Limit must be a number, 0 or more (' || r.credit_limit || ')';
            END IF;
        END IF;

        -- Already in the system
        IF v_reason = '' AND EXISTS (
               SELECT 1 FROM "CustomerProfiles"
                WHERE NOT "IsDeleted" AND "Phone1" = r.phone1) THEN
            v_reason := 'Phone 1 already belongs to a customer';
        END IF;

        IF v_reason = '' AND EXISTS (
               SELECT 1 FROM "CustomerProfiles"
                WHERE NOT "IsDeleted" AND "CustomerType" = 'Inbound'
                  AND r.nid_no <> '' AND "NidNo" = r.nid_no) THEN
            v_reason := 'NID already belongs to an Inbound customer';
        END IF;

        -- Twice in the sheet : the first row wins
        IF v_reason = '' AND EXISTS (
               SELECT 1 FROM tmp_customer_import t
                WHERE t.row_no < r.row_no AND t.phone1 = r.phone1) THEN
            v_reason := 'Phone 1 repeats an earlier row of the sheet';
        END IF;

        IF v_reason = '' AND EXISTS (
               SELECT 1 FROM tmp_customer_import t
                WHERE t.row_no < r.row_no AND r.nid_no <> ''
                  AND t.nid_no = r.nid_no) THEN
            v_reason := 'NID repeats an earlier row of the sheet';
        END IF;

        IF v_reason <> '' THEN
            UPDATE tmp_customer_import
               SET result = 'SKIPPED : ' || v_reason
             WHERE row_no = r.row_no;

            v_skipped := v_skipped + 1;
            CONTINUE;
        END IF;

        -- Location (optional) : display name "Mirpur, Dhaka" or the
        -- location name; left empty when not found or not unique
        IF r.location_text <> '' THEN
            SELECT COUNT(*), MIN("LocationId")
              INTO v_loc_count, v_location
              FROM "Locations"
             WHERE NOT "IsDeleted" AND "IsActive"
               AND lower("DisplayName") = lower(r.location_text);

            IF v_loc_count <> 1 THEN
                SELECT COUNT(*), MIN("LocationId")
                  INTO v_loc_count, v_location
                  FROM "Locations"
                 WHERE NOT "IsDeleted" AND "IsActive"
                   AND lower("LocationName") = lower(r.location_text);
            END IF;

            IF v_loc_count <> 1 THEN
                v_location := NULL;
            END IF;
        END IF;

        -- Codes
        v_cib_no    := v_cib_no + 1;
        v_ledger_no := v_ledger_no + 1;

        -- Corporate : no NID, Date of Birth or parents (as the form)
        IF r.is_corporate THEN
            r.nid_no      := '';
            r.father_name := '';
            r.mother_name := '';
            v_dob         := NULL;
        END IF;

        v_name    := r.customer_name;
        v_code    := 'CIB-' || lpad(v_cib_no::text, 6, '0');
        v_ledger  := v_parent || lpad(v_ledger_no::text, 5, '0');
        v_display := v_name || ' - ' || r.phone1;

        INSERT INTO "CustomerProfiles"
        (
            "CustomerType", "CustomerCode", "PreviousCode",
            "CustomerName", "DisplayName", "FatherName", "MotherName",
            "DateOfBirth", "PhotoPath",
            "Phone1", "Phone2", "Email",
            "NidNo", "DrivingLicenseNo",
            "PresentAddress", "PermanentAddress", "RegistrationAddress",
            "LocationId",
            "ReceivableLedgerCode", "ReceivableLedgerName",
            "CreditLimit", "IsWalkIn", "IsCorporate", "TinNo", "BinNo",
            "Remarks",
            "IsActive", "IsDeleted", "CreatedBy", "CreatedDate"
        )
        VALUES
        (
            'Inbound', v_code, '',
            v_name, v_display, r.father_name, r.mother_name,
            v_dob, '',
            r.phone1, r.phone2, r.email,
            r.nid_no, r.driving_license,
            r.present_address, r.permanent_addr, r.registration_addr,
            v_location,
            v_ledger, v_display,
            v_credit, false, r.is_corporate, '', '',
            r.remarks,
            r.status_text <> 'inactive', false, v_user_id, CURRENT_TIMESTAMP
        );

        INSERT INTO "GeneralLedgers"
        (
            "AccountClassId", "AccountGroupId", "AccountSubGroupId",
            "ClassCode", "Mode", "GroupCode", "SubGroupCode",
            "LedgerCode", "LedgerName", "Remarks",
            "IsActive", "IsDeleted", "CreatedBy", "CreatedDate"
        )
        VALUES
        (
            sg."AccountClassId", sg."AccountGroupId", sg."AccountSubGroupId",
            sg."ClassCode", sg."Mode", sg."GroupCode", sg."SubGroupCode",
            v_ledger, v_display,
            'System generated from Customer Profiles ' || v_code || ' (receivable).',
            true, false, v_user_id, CURRENT_TIMESTAMP
        );

        UPDATE tmp_customer_import
           SET result        = 'ADDED',
               customer_code = v_code,
               ledger_code   = v_ledger,
               location_name = CASE
                                   WHEN r.location_text = '' THEN ''
                                   WHEN v_location IS NULL THEN '(not found : left empty)'
                                   ELSE (SELECT "DisplayName" FROM "Locations" WHERE "LocationId" = v_location)
                               END
         WHERE row_no = r.row_no;

        v_added := v_added + 1;
    END LOOP;

    RAISE NOTICE 'Inbound import : % added, % skipped.', v_added, v_skipped;
END $$;

-- --------------------------------------------------------------
-- Result : one line per sheet row
-- --------------------------------------------------------------
SELECT row_no        AS "Row",
       sl            AS "SL",
       customer_name AS "Customer Name",
       phone1        AS "Phone 1",
       nid_no        AS "NID",
       result        AS "Result",
       customer_code AS "Code",
       ledger_code   AS "Ledger",
       location_name AS "Location"
  FROM tmp_customer_import
 ORDER BY (result = 'ADDED'), row_no;
